UPDATE `script_texts` SET `content_loc1` = '이 어리석은 이방인 놈들! 감히 여길 들어와 내 위대한 작업을 방해하다니. 브루디, 저놈들을 잡아라, 파괴해라!' WHERE `entry` = -1999955;
