UPDATE `script_texts` SET `content_loc1` = '네가 고위 십장에게 상대가 된다고 생각하느냐? 검은바위의 분노를 느껴라!' WHERE `entry` = -1999953;
UPDATE `script_texts` SET `content_loc1` = '바쁘게 움직이는 녀석들이 보이지 않는군, 우리에겐 한 달 내내 시간이 있는 게 아니다!' WHERE `entry` = -1999952;
