UPDATE `script_texts` SET `content_loc1` = '네가 내 아버지의 검을 들고 있구나. 내 군대는 너의 지휘 하에 있다, 나으리. 그들을 이끌라... 정화하라... 불순한 자들은 제거되어야 한다. 그들의 오염을 씻어내어야 한다.' WHERE `entry` = -1999920;
