UPDATE `script_texts` SET `content_loc1` = '좋아 펭구스, 어디 있는 거냐?! 나한테 豺狼人 연인이라고 놀려댔지, 머통에 망치 맛을 보여주마!' WHERE `entry` = -1900047;
UPDATE `script_texts` SET `content_loc1` = '이봐, 펭구스가 누구더러 豺狼人 연인이래?! 죄수들을 왕에게 데려가라. 무기를 들린 채로 데려가서 왕에게 놈들이 위협이 된다는 걸 보여주다니 스마트하군. 난 펭구스 놈을 때려눕힐 때 개소리를 하나 가볼 테다! 하!' WHERE `entry` = -1900046;
UPDATE `script_texts` SET `content_loc1` = '너희 나한테 안 된다, 송사리들아! 내가 이제 왕이고, 영원히 왕으로 남을 것이다!!!' WHERE `entry` = -1900045;
