UPDATE `script_texts` SET `content_loc1` = '아무도 날 지나쳐 왕을 위협하진 못한다! 으아, 받아라!!' WHERE `entry` = -1900038;
UPDATE `script_texts` SET `content_loc1` = '이 조그만 놈들을 지어부수도록 도와라!' WHERE `entry` = -1900037;
UPDATE `script_texts` SET `content_loc1` = '그래, 놈이 완전히 죽었군. 그럼 자네들이 새 왕이야.. 뭐, 너희 모두 말이지! 고르독은 이제 자네들 거라네, 두목! 나와 이야기해서 왕이 되는 것에 대한 모든 걸 배워보게나! 난... 그 녀석의 비서였지! 그래, 그래서 내가 꾀돌이라고 불리는 거라네!' WHERE `entry` = -1900013;
UPDATE `script_texts` SET `content_loc1` = '이럴 수가! 왕이 죽다니! 어... 새로운 왕에게 만세를! 그래!' WHERE `entry` = -1900012;
UPDATE `script_texts` SET `content_loc1` = '왕이 죽었다 - 이럴 수가! 꾀돌이 미즐을 불러라! 놈이 다음에 뭘 해야 할지 알고 있을 거다!' WHERE `entry` = -1900011;
UPDATE `script_texts` SET `content_loc1` = '케이나에 대해 이야기할 것이 많다. 모험가여, 안도할로 돌아가 나에게 말하도록 해라.' WHERE `entry` = -1780408;
UPDATE `script_texts` SET `content_loc1` = '이쯤 해두지! 너 따위 해충들과 상대할 시간은 없다. 주인님의 계획이 거의 완성되었고 내 교란 작전은 성공했으니까!' WHERE `entry` = -1780407;
UPDATE `script_texts` SET `content_loc1` = '내가 도와주지! 다 죽여버리자!' WHERE `entry` = -1780406;
UPDATE `script_texts` SET `content_loc1` = '모험가여, 내가 약화시킬 테니 그대는 그녀를 끝장내게.' WHERE `entry` = -1780405;
UPDATE `script_texts` SET `content_loc1` = '내가 사냥하고 있던 게 바로 저 여자야! 이름은 안트노르미지. 아직 상대할 준비가 안 됐지만, 선택의 여지가 없구나!' WHERE `entry` = -1780404;
UPDATE `script_texts` SET `content_loc1` = '너 뒤에 있는 저건 뭐냐?!' WHERE `entry` = -1780403;
UPDATE `script_texts` SET `content_loc1` = '아니 잠깐만! 내 말 좀 들어봐! 난 더 큰 위협을 쫓으러 온 거고 그녀가 오고 있는 중이야. 쫓아야 할 건 내가 아니라고!' WHERE `entry` = -1780402;
UPDATE `script_texts` SET `content_loc1` = '악당 놈, 드디어 찾았다! 도망칠 곳은 없다!' WHERE `entry` = -1780401;
UPDATE `script_texts` SET `content_loc1` = '$N님, 일찍 오셨군요! 이런 행운이! 마침내 추적에 성공한 것 같-' WHERE `entry` = -1780400;
UPDATE `script_texts` SET `content_loc1` = '칼림도어의 힘이 승리했다! 그라지 군대의 마지막 잔당이 패배하여 고대 도시 요새인 안키라즈로 후퇴한다. 칼림도어에 흩어져 있던 그라지 공명 수정들은 나타났던 것 만큼이나 신속히 사라져, 파괴된 대지 외엔 아무것도 남기지 않았다.' WHERE `entry` = -1780312;
UPDATE `script_texts` SET `content_loc1` = '칼림도어를 위한 최후의 전투가 다가왔다. 칼림도어의 힘 사령관이 그의 부대에게 안키라즈로 진격하여 길을 막는 모든 것을 파괴하라고 명령한다..' WHERE `entry` = -1780311;
UPDATE `script_texts` SET `content_loc1` = '전진하라! 안키라즈로!' WHERE `entry` = -1780310;
UPDATE `script_texts` SET `content_loc1` = '너희 중 그 누가 이러한 죽음을 거부하겠느냐? 이런 영광을?' WHERE `entry` = -1780309;
UPDATE `script_texts` SET `content_loc1` = '오늘, 이 전장에서 죽는 것은 오크다운 죽음을 맞이하는 것이다. 오늘 죽는 것은 우리 어린것들을 위해 죽는 것이다. 우리 노인들을 위해. 우리... 사랑하는 이들을 위해' WHERE `entry` = -1780308;
UPDATE `script_texts` SET `content_loc1` = '우리는 방어한다. 우리는 일어선다. 우리는 하나임을 보여준다. 단결하여. 우리는 파괴한다. 그들의 신은 쓰러질 것이다.' WHERE `entry` = -1780307;
UPDATE `script_texts` SET `content_loc1` = '그렇다면 우리의 신들을 위해서는?' WHERE `entry` = -1780306;
UPDATE `script_texts` SET `content_loc1` = '우리 어린것들의 목숨을 짓밟을 기회를 기다리면서. 제 지나가는 길의 모든 것을 죽이기 위해. 놈들은 자신들의 신을 위해 이 짓을 한다.' WHERE `entry` = -1780305;
UPDATE `script_texts` SET `content_loc1` = '분쟁이 이 땅을 가득 채우고 군단과 스컬지가 우리 집을 짓밟고 가족을 죽였던 그 시절에 – 이 곤충 놈들은 우리 발밑에 서식하고 있었다. 우리 집 아래에서 – 기다리면서' WHERE `entry` = -1780304;
UPDATE `script_texts` SET `content_loc1` = '너희 중 일부는 전장에서 싸워보지 못했을 것이다. 수년 동안 우리에게 평화가 함께했으니. 오랫동안 우리는 나태하게 앉아있었으나, 오랫동안 싸워왔기도 하다.' WHERE `entry` = -1780303;
UPDATE `script_texts` SET `content_loc1` = '오크 – 진정한 오크 전사 – 가 바라는 것은 오직 하나: 증오하는 적에 맞서 전투의 영광 속에서 죽는 것 뿐이다.' WHERE `entry` = -1780302;
UPDATE `script_texts` SET `content_loc1` = '너희는 내가 칼림도어의 힘의 사령관임을 알고 있다.' WHERE `entry` = -1780301;
