UPDATE `script_texts` SET `content_loc1` = '너희가 어떻게든 나를 제압하더라도, 내가 카림도어가 가질 수 있는 유일한 희망을 파괴하기 전까지는 안 된다면 기막히지 않겠느냐? 기대감으로 머리가 어지러울 지경이구나. 머지않아... 머지않아 잿더미가 되리라.' WHERE `entry` = -1469041;
