UPDATE `script_texts` SET `content_loc1` = '글쎄요. 그가 우리 모두 사실 어떤 존재의 상상 속 산물일 뿐이며, 단지 그 개인적인 유흥거리로 사용될 뿐이라고 우리를 설득하려 했던 때보다 더하진 않을 것 같은데요. 가족들과 식사하는 자리에서 아주 분위기 좋아졌었죠.' WHERE `entry` = -1000525;
