UPDATE `script_texts` SET `content_loc1` = '여기 온 첫날 이 동굴을 발견했죠. 돌에 담긴 에너지를 우리에게 유리하게 활용할 수 있을 거라 믿습니다.' WHERE `entry` = -1000265;
UPDATE `script_texts` SET `content_loc1` = '좋아요, $N님. 동굴로 절 따라오세요. 거기서 룬석의 힘을 이 고글에 담는 시도를 해볼 겁니다.' WHERE `entry` = -1000264;
UPDATE `script_texts` SET `content_loc1` = '행운을 빕니다 이방인이여, 샤트라스 도시에 오신 것을 환영합니다.' WHERE `entry` = -1000255;
UPDATE `script_texts` SET `content_loc1` = '카드가가 당신을 다시 만날 준비가 되었을 겁니다. 샤타르를 섬기려면 대부분 알도르 사제회나 점술가 길드 중 한쪽과 동맹을 맺어야 한다는 점을 명심하세요. 한 집단의 호의를 얻으면 다른 집단의 반감을 사게 될 것입니다.' WHERE `entry` = -1000254;
UPDATE `script_texts` SET `content_loc1` = '그들의 적개심이 어찌나 큰지, 그곳의 나루를 도우러 파견되는 영광을 차지하고자 경쟁할 정도입니다. 매일 그 결정은 이곳에서 아달에 의해 내려집니다. 군대는 어둠달로 향하기 전 아달의 축복을 받기 위해 이곳에 모입니다.' WHERE `entry` = -1000253;
UPDATE `script_texts` SET `content_loc1` = '그곳에서 그는 알도르와 점술가 길드의 도움을 받아 일리단과의 전쟁을 이어가고 있습니다. 두 세력은 여전히 자신들의 오랜 숙원을 포기하지 않았지만 말입니다.' WHERE `entry` = -1000252;
UPDATE `script_texts` SET `content_loc1` = '샤트라스를 향한 공격은 계속되었지만, 보시다시피 도시는 함락되지 않았습니다. 오히려 시리라 알려진 나루가 일리단의 턱밑인 어둠달 골짜기로 성공적인 침투를 이끌었지요.' WHERE `entry` = -1000251;
UPDATE `script_texts` SET `content_loc1` = '알도르의 가장 신성한 사원과 그 주변 거처는 위쪽 제단에 있습니다. 신성한 장소인 만큼 입회한 자들만 출입할 수 있죠.' WHERE `entry` = -1000250;
UPDATE `script_texts` SET `content_loc1` = '사제단의 많은 이들이 지금은 나루를 섬기겠다고 맹세한 바로 그 마법학자들에게 목숨을 잃었습니다. 그들은 이전의 적들과 도시를 공유하는 것을 반기지 않았습니다.' WHERE `entry` = -1000249;
UPDATE `script_texts` SET `content_loc1` = '알도르는 빛의 추종자들이며 용서와 구원은 그들이 이해하는 가치입니다. 하지만 그들은 캘타스의 지휘 아래 있던 혈엘프들의 행위를 잊기는 어려워했지요.' WHERE `entry` = -1000248;
UPDATE `script_texts` SET `content_loc1` = '나루는 탈영병들을 받아들였고, 이들은 점술가 길드로 알려지게 되었습니다. 그들의 거처는 위쪽 제단에 위치해 있지요. 점술가 길드에 입회한 이들만 들어갈 수 있습니다.' WHERE `entry` = -1000247;
UPDATE `script_texts` SET `content_loc1` = '보렌탈과 그 추종자들의 이탈은 캘타스의 군대가 입은 가장 큰 손실이었습니다. 게다가 그들은 그냥 혈엘프가 아니었지요. 캘타스 학자들과 마법학자들 중 가장 뛰어나고聪명한 이들 다수가 보렌탈의 영향력에 설득당했던 것입니다.' WHERE `entry` = -1000246;
UPDATE `script_texts` SET `content_loc1` = '나루가 다가오자, 보렌탈은 무릎을 꿇고 이렇게 말했습니다. "환영 속에서 당신을 보았습니다, 나루여. 내 종족이 살아남을 유일한 희망은 당신에게 있습니다. 나와 내 추종자들은 당신을 섬기고자 여기에 왔습니다."' WHERE `entry` = -1000245;
UPDATE `script_texts` SET `content_loc1` = '혈엘프들이 도시 수호자들 앞에서 무기를 내려놓은 것입니다. 보렌탈이라 알려진 혈엘프 원로인 그들의 리더는 빛의 정원으로 성큼성큼 들어가 아달과의 면담을 요구했습니다.' WHERE `entry` = -1000244;
UPDATE `script_texts` SET `content_loc1` = '혈엘프 연대가 바로 이 다리를 건널 때, 알도르의 총사령관들과 구원자들은 빛의 정원을 지키기 위해 배수진을 쳤습니다. 하지만 그때 뜻밖의 일이 일어났습니다.' WHERE `entry` = -1000243;
UPDATE `script_texts` SET `content_loc1` = '하지만 얼마 지나지 않아 도시는 다시 한번 공격을 받게 되었습니다. 이번 공격은 일리단의 군대로부터 시작되었지요. 일리단의 동맹인 캘타스 선스트라이더가 파견한 대규모 혈엘프 연대가 도시를 잿더미로 만들기 위해 진격해 왔습니다.' WHERE `entry` = -1000242;
UPDATE `script_texts` SET `content_loc1` = '알도르라고 알려진 사제단은 나루가 돌아왔다는 소문이 퍼지자 빠르게 세력을 회복했고 곧 재건이 시작되었습니다. 폐허가 된 사원은 이제 부상당한 난민들을 위한 치료소로 사용되고 있지요.' WHERE `entry` = -1000241;
UPDATE `script_texts` SET `content_loc1` = '그들은 샤트라스 도시 유적으로 이끌려 왔는데, 바로 이 자리의 폐허가 된 사원 내부에서 드레나이 사제단의 일부 생존자들이 의식을 치르고 있었지요.' WHERE `entry` = -1000240;
UPDATE `script_texts` SET `content_loc1` = '샤타르, 즉 "빛에서 태어난 자들"은 불타는 군단의 악마들과 싸우기 위해 아웃랜드로 온 나루들입니다.' WHERE `entry` = -1000239;
UPDATE `script_texts` SET `content_loc1` = '고난의 거리로 가봅시다. 외곽 지역에 있는 얼마 안 되는 안전지대 중 하나이다 보니, 샤트라스에는 과거와 현재의 온갖 전쟁에서 도망쳐 온 난민들이 몰려들었다는 점을 일러두겠습니다.' WHERE `entry` = -1000238;
UPDATE `script_texts` SET `content_loc1` = '도시는 유적과 어둠 속에 방치되어 있었습니다... 샤타르가 도착할 때까지는 말입니다.' WHERE `entry` = -1000237;
UPDATE `script_texts` SET `content_loc1` = '불타는 군단이 오크들을 부추겨 드레나이를 공격했을 때, 가장 치열한 전투가 이곳에서 벌어졌습니다. 드레나이들은 필사적으로 싸웠으나 결국 도시는 함락되고 말았습니다.' WHERE `entry` = -1000236;
UPDATE `script_texts` SET `content_loc1` = '샤트라스는 한때 이 세계 드레나이의 수도였습니다. 그 이름은 "빛의 거처"라는 뜻이지요.' WHERE `entry` = -1000235;
UPDATE `script_texts` SET `content_loc1` = '나를 따라오시오, 이방인이여. 오래 걸리지 않을 거요.' WHERE `entry` = -1000234;
UPDATE `script_texts` SET `content_loc1` = '우리의 시간이 끝났습니다, $N님. 행운이란 게 존재한다면 행운을 빌어 드리고 싶군요.' WHERE `entry` = -1000230;
UPDATE `script_texts` SET `content_loc1` = '이 시간의 길에 대해 아는 것은 하이잘 산으로 연결된다는 것뿐입니다. 무한의 용군단은 우리의 개입을 막기 위해 수단과 방법을 가리지 않고 있습니다. 우리는 거의 아무것도 모릅니다, 필멸자여. 소리도르미가 시간의 길의 방어를 뚫으려 시도하고 있지만 아직 성공하지 못했습니다. 당신이 이 충돌을 해결할 유일한 희망일지도 모릅니다.' WHERE `entry` = -1000229;
UPDATE `script_texts` SET `content_loc1` = '시간의 길은 현재 가장 적은 재앙부터 가장 치명적인 재앙까지 순서대로 분류되어 있습니다. 이것들이 모두 \'재앙\'으로 분류되어 있다는 점에 유의하세요. 즉, 단 하나의 시간의 길이라도 붕괴하면 당신들의 세상이 끝난다는 것을 의미합니다. 보내지는 영웅들과 모험가들이 자신의 능력에 가장 잘 맞는 시간의 길을 알 수 있도록 이렇게 분류했을 뿐입니다.' WHERE `entry` = -1000228;
UPDATE `script_texts` SET `content_loc1` = '이 시간의 길은 현재 붕괴하고 있습니다. 과거, 현재, 미래에 어떤 영향을 미칠지는 알 수 없습니다...' WHERE `entry` = -1000227;
UPDATE `script_texts` SET `content_loc1` = '우리는 이 시간의 길에 대한 정보가 거의 없습니다. 사아트가 파견되어 현재 내부에 있습니다. 그가 보내온 정보에 따르면 무한의 용군단이 다시 한번 시간을 바꾸려 시도하고 있다고 합니다. 어쩌면 어둠의 문이 열리는 것을 방해하려는 목표일까요? 그렇지 않기를 바랄 뿐입니다...' WHERE `entry` = -1000226;
UPDATE `script_texts` SET `content_loc1` = '이 시간의 길은 큰 혼란에 빠져 있습니다! 현재 내부에서 질서를 회복하려는 요원들이 활동 중입니다. 제가 얻은 정보에 따르면 스랄의 자유가 위협받고 있다고 합니다. 무한의 용군단이라 불리는 사악한 조직이 그의 탈출을 막으려 하고 있습니다. 외부의 도움이 없다면 모든 것이 무산될까 두렵습니다.' WHERE `entry` = -1000225;
UPDATE `script_texts` SET `content_loc1` = '당신이 보고 계신 이 터널들을 시간의 길이라고 부릅니다. 그 수는 무한하지요. 현재 당신의 현실에 존재하는 것들은 주인님께서 \'분쟁 지역\'으로 간주하신 곳들입니다. 이 분쟁 지역들은 주제는 완전히 다를지라도 원인은 항상 공유합니다. 즉, 동일한 시공간적 교란의 결과로 존재하는 것이지요. 내부로 들어간다면 이 점을 명심하세요...' WHERE `entry` = -1000224;
UPDATE `script_texts` SET `content_loc1` = '일반적인 시간의 유지 관리는 시간의 수호자들만으로도 충분합니다. 사악한 법사가 현재의 신분이나 부를 높이기 위해 과거의 무언가를 바꾸려 하는 소소한 교란은 우리 선에서 처리할 수 있습니다.' WHERE `entry` = -1000223;
UPDATE `script_texts` SET `content_loc1` = '시간의 파수꾼으로서 우리는 노즈도르무님의 영역을 지키고 가꿉니다. 지금 주인님께서 자리를 비우셨는데, 이는 누군가가 시간을 크게 바꾸려 시도하고 있음을 의미하지요. 주인님은 결코 필멸자의 일에 관여하지 않으시지만, 타인에 의해 변형된 시간은 바로잡으십니다. 이 점에 있어서 그분은 능동적이시지요.' WHERE `entry` = -1000222;
UPDATE `script_texts` SET `content_loc1` = '이곳에서 찾을 수 있는 진실은 단 두 가지뿐입니다. 첫째, 시간은 혼란스럽고 항상 유동적이며 완벽히 바뀔 수 있다는 것. 둘째, 지각이 현실을 결정짓지 않는다는 것입니다.' WHERE `entry` = -1000221;
UPDATE `script_texts` SET `content_loc1` = '저를 따라오세요.' WHERE `entry` = -1000220;
UPDATE `script_texts` SET `content_loc1` = '이상하게 들리시겠지만 대부분의 필멸자들은 이곳에서 보는 것을 실제 이해하지 못합니다. 그들이 보는 것은 종종 그들 자신의 현실에 대한 인식에 기반하지 않기 때문이지요.' WHERE `entry` = -1000219;
UPDATE `script_texts` SET `content_loc1` = '시간의 동굴이 항상 필멸자들에게 열려 있었는지는 저희도 알 수 없습니다. 시간을 지배하는 자는 끊임없이 움직이며 자신의 뜻대로 시간을 바꾸므로 진실은 알 수 없지요. 지금 당신이 보는 것도 내일이면 존재하지 않을 수 있습니다. 깨어났을 때 이곳에 대한 기억이 전혀 없을 수도 있죠.' WHERE `entry` = -1000218;
UPDATE `script_texts` SET `content_loc1` = '어서 오세요, $N님. 동굴 안으로 안내해 드릴 테니 잘 따라오세요.' WHERE `entry` = -1000217;
